#!/usr/bin/env node
// Copies the pure logic the Edge Functions share with the app into
// supabase/functions/_shared/generated/ (Edge Functions are deployed on their own and cannot
// import from src/). `--check` fails when the generated files are stale (used by `npm run check`).
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outDir = join(root, 'supabase/functions/_shared/generated');
const header = (source) =>
  `// GENERATED by scripts/sync-shared.mjs from ${source}. Do not edit: run \`npm run sync:shared\`.\n`;

const { SKIP_LINES } = await import(pathToFileURL(join(root, 'content/skip-lines.ts')).href);

const files = {
  'skipDraw.ts':
    header('src/domain/skipDraw.ts') + readFileSync(join(root, 'src/domain/skipDraw.ts'), 'utf8'),
  'skipLineIds.ts':
    header('content/skip-lines.ts') +
    `export const SKIP_LINE_IDS: readonly string[] = [\n${SKIP_LINES.map((l) => `  '${l.id}',`).join('\n')}\n];\n`,
};

const check = process.argv.includes('--check');
let stale = false;
mkdirSync(outDir, { recursive: true });
for (const [name, content] of Object.entries(files)) {
  const path = join(outDir, name);
  let current = null;
  try {
    current = readFileSync(path, 'utf8');
  } catch {
    current = null;
  }
  if (current === content) continue;
  if (check) {
    console.error(`✗ ${name} est périmé : lance npm run sync:shared`);
    stale = true;
  } else {
    writeFileSync(path, content);
    console.log(`→ ${name}`);
  }
}
if (stale) process.exit(1);
